        public static void Install(SnowmanMatch m)
        {
            if(EditorApplication.isPlaying||EditorApplication.isCompiling||m==null||m.transform.Find("Winter village workshop")!=null||(!string.IsNullOrEmpty(m.gameObject.scene.path)&&m.gameObject.scene.path!=Scene))throw new InvalidOperationException("Stopped NEW unauthored Snowman scene required.");var root=new GameObject("Winter village workshop").transform;root.SetParent(m.transform,false);
            var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckAvalancheEscape/Materials/Packed Weatherade snow roads.mat");if(source==null)throw new InvalidOperationException("Existing Weatherade snow foundation required.");var snow=new Material(source){name="Permanent village Weatherade snow"};if(snow.HasProperty("_CoverageAmount"))snow.SetFloat("_CoverageAmount",1);AssetDatabase.CreateAsset(snow,"Assets/"+Folder+"/Materials/Permanent village Weatherade snow.mat");var grip=SportsEventAuthoring.Contact(Folder,"Packed winter ground contact",.65f,.015f);SportsEventAuthoring.Box("Continuous solid winter meadow",new Vector3(0,-.6f,-25),new Vector3(150,1.2f,240),snow,grip,root);
            m.patches=new SnowmanSnowPatch[3];float[] depths={.25f,.112f,.043f};for(int i=0;i<3;i++){var lane=SportsEventAuthoring.Box("Finite drift lane "+i,new Vector3((i-1)*10,.01f,-46),new Vector3(8,.04f,76),snow,grip,root);var patch=lane.AddComponent<SnowmanSnowPatch>();patch.ground=lane.GetComponent<BoxCollider>();patch.depth=depths[i];patch.ResetSnow();m.patches[i]=patch;var sign=SportsEventAuthoring.Label("Gathering lane label",new[]{"DEEP DRIFT · BASE","SOFT DRIFT · MIDDLE","POWDER · HEAD"}[i],new Vector3((i-1)*10,2,-88),.12f,new Color(.05f,.2f,.3f));sign.transform.SetParent(root,true);}
            var blue=SportsEventAuthoring.Mat(Folder,"Winter workshop blue enamel",new Color(.05f,.35f,.5f),.5f);var woodSource=AssetDatabase.LoadAssetAtPath<Material>("Assets/RoadPropsPack/URP/Materials/M_WoodBox.mat");if(woodSource==null)throw new InvalidOperationException("Owned timber material required.");var wood=new Material(woodSource){name="Warm workshop timber"};AssetDatabase.CreateAsset(wood,"Assets/"+Folder+"/Materials/Warm workshop timber.mat");
            m.buildCenter=new GameObject("Real snowman foundation center").transform;m.buildCenter.SetParent(root,false);m.buildCenter.position=new Vector3(0,.15f,22);var pad=SportsEventAuthoring.Box("Raised physical sculpture foundation",new Vector3(0,0,22),new Vector3(14,.3f,14),snow,grip,root);m.foundation=pad.GetComponent<Collider>();m.foundationBody=pad.AddComponent<Rigidbody>();m.foundationBody.isKinematic=true;m.foundationBody.useGravity=false;
            var ballMat=new Material(snow){name="Hand packed crystalline snow"};AssetDatabase.CreateAsset(ballMat,"Assets/"+Folder+"/Materials/Hand packed crystalline snow.mat");m.balls=new SnowmanBall[3];var physical=SportsEventAuthoring.Contact(Folder,"Real snow rolling and packing contact",.65f,0);var sphereSource=GameObject.CreatePrimitive(PrimitiveType.Sphere);var mesh=UnityEngine.Object.Instantiate(sphereSource.GetComponent<MeshFilter>().sharedMesh);UnityEngine.Object.DestroyImmediate(sphereSource);mesh.name="Lumpy hand packed snow sphere";var vertices=mesh.vertices;for(int v=0;v<vertices.Length;v++){var n=vertices[v].normalized;vertices[v]=n*(.5f+Mathf.Sin(n.x*23+n.y*11+n.z*17)*.009f+Mathf.Sin(n.x*37-n.y*31)*.006f);}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Materials/Lumpy hand packed snow sphere.asset");
            for(int i=0;i<3;i++){var g=new GameObject("Physical snowball · "+new[]{"base","middle","head"}[i]);g.transform.SetParent(root,false);g.transform.position=new Vector3((i-1)*10,.75f,-80);var shell=new GameObject("Actual rolling snow crystal surface",typeof(MeshFilter),typeof(MeshRenderer));shell.transform.SetParent(g.transform,false);shell.GetComponent<MeshFilter>().sharedMesh=mesh;shell.GetComponent<MeshRenderer>().sharedMaterial=ballMat;shell.transform.localScale=Vector3.one*1.5f;var c=g.AddComponent<SphereCollider>();c.radius=.75f;c.sharedMaterial=physical;c.contactOffset=.005f;var rb=g.AddComponent<Rigidbody>();rb.mass=62;rb.interpolation=RigidbodyInterpolation.Interpolate;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;rb.linearDamping=.03f;rb.angularDamping=.04f;rb.maxAngularVelocity=14;rb.maxDepenetrationVelocity=3;rb.solverIterations=28;rb.solverVelocityIterations=14;var b=g.AddComponent<SnowmanBall>();b.match=m;b.role=i;b.stableId="snowman.ball."+new[]{"base","middle","head"}[i];b.radius=.75f;b.maximumRadius=new[]{3f,2.4f,1.8f}[i];b.body=rb;b.sphere=c;b.shell=shell.transform;b.contact=g.AddComponent<SportsSnowBodyContact>();m.balls[i]=b;}
            m.trucks=new SportsEventTruck[4];for(int i=0;i<4;i++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(LWS.TruckFareFight.Editor.FareFightVehicleAuthoring.PrefabPath);if(prefab==null)throw new InvalidOperationException("Existing full NWH tractor required; never regenerated.");var truck=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var t=truck.GetComponent<SportsEventTruck>();t.session=m;t.slot=i;t.tractorMotor.settings=m.settings;truck.transform.position=i<3?new Vector3((i-1)*10,.7f,-87):new Vector3(27,.7f,-12);m.trucks[i]=t;EditorUtility.SetDirty(t);EditorUtility.SetDirty(t.tractorMotor);}
            m.hoist=m.gameObject.AddComponent<JengaCrane>();m.hoist.ceiling=22;m.hoist.parkHeight=16;m.hoist.travelSpeed=4;m.hoist.liftSpeed=2.8f;var gantry=new GameObject("Working winter construction hoist").transform;gantry.SetParent(root,false);for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Beam(gantry,new Vector3(x*22,0,z*23),new Vector3(x*22,22,z*23),.35f,wood,"Timber snow workshop gantry");for(int z=-1;z<=1;z+=2)Beam(gantry,new Vector3(-24,22,z*23),new Vector3(24,22,z*23),.25f,blue,"Physical hoist rail");var bridge=new GameObject("Motor bridge").transform;bridge.SetParent(gantry,false);Beam(bridge,new Vector3(0,0,-23),new Vector3(0,0,23),.25f,blue,"Moving bridge");m.hoist.bridge=bridge;var trolley=new GameObject("Cable reel trolley").transform;trolley.SetParent(gantry,false);Prop(trolley,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_CableReel01 Variant.prefab",Vector3.zero,new Vector3(2,1.5f,2));m.hoist.trolley=trolley;var hook=new GameObject("Physical motor driven snowball spreader");hook.transform.SetParent(gantry,false);hook.transform.position=new Vector3(16,16,0);var motor=hook.AddComponent<Rigidbody>();motor.isKinematic=true;motor.useGravity=false;motor.interpolation=RigidbodyInterpolation.Interpolate;m.hoist.spreader=motor;Beam(hook.transform,new Vector3(-1,0,0),new Vector3(1,0,0),.12f,blue,"Soft snow gripping spreader");var line=new GameObject("Visible actual hoist cable").AddComponent<LineRenderer>();line.transform.SetParent(gantry,false);line.positionCount=2;line.startWidth=line.endWidth=.07f;line.sharedMaterial=wood;m.hoist.hoist=line;
            m.supply=new GameObject("Physical decoration cabinet interaction").transform;m.supply.SetParent(root,false);m.supply.position=new Vector3(28,.5f,-3);Prop(root,"Assets/LeartesStudios/Garage Warehouse Environment/Art/Prefabs/SM_ToolCabinet_01.prefab",m.supply.position,new Vector3(5,3,2));Decorations(m,root,wood);
            for(int side=-1;side<=1;side+=2)for(int n=0;n<3;n++)Cabin(root,new Vector3(side*55,0,-45+n*44),wood,snow,blue);for(int i=0;i<45;i++){float a=i*2.39996f;var pos=new Vector3(Mathf.Cos(a)*(80+i%3*9),0,-25+Mathf.Sin(a)*(105+i%4*9));Prop(root,"Assets/Toby Fredson/Rocky Hills Environment - Whitebark Pine/RHEWP_Demo/Prefabs/Prefabs_Vegetation/PV_Trees/WhitebarkPineRHEP_B.prefab",pos,new Vector3(8,16+i%3*3,8));}
            var ice=SportsEventAuthoring.Mat(Folder,"Opaque frozen village lake",new Color(.25f,.52f,.65f),.82f);SportsEventAuthoring.Box("Solid frozen village lake",new Vector3(46,.01f,58),new Vector3(40,.08f,36),ice,grip,root);
            var terrainSource=AssetDatabase.LoadAssetAtPath<TerrainData>("Assets/TruckSkyTow/Art/Arctic fjord terrain.asset");if(terrainSource==null)throw new InvalidOperationException("Existing owned Arctic mountain terrain required.");var landscape=Terrain.CreateTerrainGameObject(terrainSource);landscape.name="Existing Arctic mountain landscape around winter village";landscape.transform.SetParent(root,false);landscape.transform.position=new Vector3(-1100,-400,-400);UnityEngine.Object.DestroyImmediate(landscape.GetComponent<TerrainCollider>());var terrain=landscape.GetComponent<Terrain>();float highest=float.MinValue;for(int z=-120;z<=80;z+=20)for(int x=-75;x<=75;x+=15)highest=Mathf.Max(highest,terrain.SampleHeight(new Vector3(x,0,z)));landscape.transform.position=new Vector3(-1100,-highest-2,-400);var terrainMaterial=SportsEventAuthoring.Mat(Folder,"Existing Arctic terrain URP presentation",Color.white);terrainMaterial.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");if(terrainMaterial.shader==null)throw new InvalidOperationException("Installed URP Terrain Lit shader required.");terrain.materialTemplate=terrainMaterial;terrain.drawInstanced=true;terrain.heightmapPixelError=12;
            m.spectators=Crowd(root);m.broadcast=SportsEventAuthoring.Camera("Snowman original Cinemachine broadcast");m.cameras=new[]{m.broadcast.view};m.broadcast.Pose(new Vector3(0,4,-20),new Vector3(32,40,-50),58,true);SnowmanCollectionRackAuthoring.Install(m);
        }
        static void Prop(Transform parent,string path,Vector3 position,Vector3 size){var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(source==null)throw new InvalidOperationException("Owned winter prop required: "+path);var holder=new GameObject("Owned village prop").transform;holder.SetParent(parent,false);var g=(GameObject)PrefabUtility.InstantiatePrefab(source);g.transform.SetParent(holder,false);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var b in g.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var script in g.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);var renderers=g.GetComponentsInChildren<Renderer>(true);if(renderers.Length==0)throw new InvalidOperationException("Visible owned model required.");Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(size.x/Mathf.Max(.001f,bounds.size.x),size.y/Mathf.Max(.001f,bounds.size.y),size.z/Mathf.Max(.001f,bounds.size.z)));bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);g.transform.position-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z)-holder.position;holder.localPosition=position;}
        static void Beam(Transform p,Vector3 a,Vector3 b,float r,Material mat,string name){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(p,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);g.transform.localScale=new Vector3(r*2,(b-a).magnitude*.5f,r*2);g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
        static void Cabin(Transform parent,Vector3 pos,Material wood,Material snow,Material trim){var root=new GameObject("Purpose-authored solid warm log cabin").transform;root.SetParent(parent,false);root.localPosition=pos;var shell=root.gameObject.AddComponent<BoxCollider>();shell.center=new Vector3(0,2.5f,0);shell.size=new Vector3(12,5,8);for(int row=0;row<10;row++)for(int side=-1;side<=1;side+=2){if(side<0&&row<7){Beam(root,new Vector3(-6,row*.5f+.3f,-4),new Vector3(-1.3f,row*.5f+.3f,-4),.28f,wood,"Front timber wall beside real doorway");Beam(root,new Vector3(1.3f,row*.5f+.3f,-4),new Vector3(6,row*.5f+.3f,-4),.28f,wood,"Front timber wall beside real doorway");}else Beam(root,new Vector3(-6,row*.5f+.3f,side*4),new Vector3(6,row*.5f+.3f,side*4),.28f,wood,"Actual textured timber wall log");Beam(root,new Vector3(side*6,row*.5f+.3f,-4),new Vector3(side*6,row*.5f+.3f,4),.28f,wood,"Timber end wall log");}var glow=SportsEventAuthoring.Mat(Folder,"Warm emissive cabin windows",new Color(1,.59f,.18f),.55f);glow.EnableKeyword("_EMISSION");glow.SetColor("_EmissionColor",new Color(1,.42f,.07f)*1.7f);for(int side=-1;side<=1;side+=2){var roof=SportsEventAuthoring.Box("Snow laden pitched cabin roof",new Vector3(side*3.2f,6.4f,0),new Vector3(7.8f,.5f,11),snow,null,root);roof.transform.localRotation=Quaternion.Euler(0,0,side*-24);SportsEventAuthoring.Box("Warm glowing cabin window",new Vector3(side*3,2.5f,-4.3f),new Vector3(2,2,.2f),glow,null,root);for(int axis=0;axis<2;axis++)SportsEventAuthoring.Box("Crafted window mullion",new Vector3(side*3,2.5f,-4.42f),axis==0?new Vector3(.08f,2.1f,.06f):new Vector3(2.1f,.08f,.06f),wood,null,root);}SportsEventAuthoring.Box("Crafted timber cabin door",new Vector3(0,1.8f,-4.1f),new Vector3(2.45f,3.4f,.22f),trim,null,root);SportsEventAuthoring.Box("Timber cabin porch",new Vector3(0,.25f,-6),new Vector3(13,.5f,4),wood,null,root);SportsEventAuthoring.Box("Snowy porch step",new Vector3(0,.1f,-8.4f),new Vector3(4,.2f,1.2f),snow,null,root);var light=new GameObject("Warm night porch lamp").AddComponent<Light>();light.transform.SetParent(root,false);light.transform.localPosition=new Vector3(0,4,-5);light.type=LightType.Point;light.range=12;light.intensity=25;light.color=new Color(1,.56f,.23f);light.shadows=LightShadows.None;}

        static void Decorations(SnowmanMatch m,Transform parent,Material wood)
        {
            var templates=new GameObject("Inactive real workshop decoration templates").transform;templates.SetParent(parent,false);var carrot=SportsEventAuthoring.Mat(Folder,"Carrot orange",new Color(.95f,.28f,.035f));var coal=SportsEventAuthoring.Mat(Folder,"Coal black",new Color(.015f,.02f,.025f));var red=SportsEventAuthoring.Mat(Folder,"Knitted cranberry scarf",new Color(.72f,.025f,.06f));var blue=SportsEventAuthoring.Mat(Folder,"Knitted glacier scarf",new Color(.03f,.3f,.7f));m.decorations=new SnowmanDecorFamily[6];string[] ids={"carrot","coal","scarf","hat","arms","novelty"};for(int f=0;f<6;f++)m.decorations[f]=new SnowmanDecorFamily{id="snowman.decor."+ids[f],label=ids[f].ToUpperInvariant(),variants=new GameObject[f==2?2:f==3||f==5?3:1]};
            for(int f=0;f<6;f++)for(int v=0;v<m.decorations[f].variants.Length;v++){var g=new GameObject(m.decorations[f].id+".style."+v);g.transform.SetParent(templates,false);if(f==0){var mesh=new Mesh{name="Actual tapered carrot nose"};var verts=new List<Vector3>();var tris=new List<int>();for(int i=0;i<20;i++){float a=i*Mathf.PI/10;verts.Add(new Vector3(Mathf.Sin(a)*.28f,Mathf.Cos(a)*.28f,0));verts.Add(new Vector3(0,0,-2));}for(int i=0;i<20;i++){tris.Add(i*2);tris.Add(((i+1)%20)*2);tris.Add(i*2+1);}mesh.vertices=verts.ToArray();mesh.triangles=tris.ToArray();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Materials/Tapered carrot nose.asset");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=carrot;}
                else if(f==1){for(int i=0;i<7;i++){var rock=GameObject.CreatePrimitive(PrimitiveType.Sphere);rock.name="Actual coal face stone";rock.transform.SetParent(g.transform,false);rock.transform.localPosition=i<2?new Vector3(i==0?-.35f:.35f,.25f,-.96f):new Vector3((i-4)*.17f,-.28f-Mathf.Abs(i-4)*.04f,-.98f);rock.transform.localScale=Vector3.one*.18f;rock.GetComponent<Renderer>().sharedMaterial=coal;UnityEngine.Object.DestroyImmediate(rock.GetComponent<Collider>());}}
                else if(f==2){for(int i=0;i<32;i++){float a=i*Mathf.PI/16,b=(i+1)*Mathf.PI/16;Beam(g.transform,new Vector3(Mathf.Sin(a)*.96f,0,Mathf.Cos(a)*.96f),new Vector3(Mathf.Sin(b)*.96f,0,Mathf.Cos(b)*.96f),.16f,v==0?red:blue,"Soft knitted scarf collar");}SportsEventAuthoring.Box("Hanging knitted scarf tail",new Vector3(.45f,-.7f,-.95f),new Vector3(.28f,1.6f,.1f),v==0?red:blue,null,g.transform);}
                else if(f==3||f==5){string path=f==3?"Assets/TruckSports/Customization/Accessories/"+new[]{"hat.top","hat.party","hat.cowboy"}[v]+".prefab":"Assets/TruckSports/Customization/Accessories/"+new[]{"dashboard.cat","dashboard.wolf","rear.party"}[v]+".prefab";Prop(g.transform,path,Vector3.zero,new Vector3(f==3?2:1,f==3?1.3f:1,f==3?2:1));}
                else for(int side=-1;side<=1;side+=2){Vector3 end=new Vector3(side*2.8f,.4f,0);Beam(g.transform,new Vector3(side*.8f,0,0),end,.1f,wood,"Actual branch snowman arm");for(int finger=0;finger<3;finger++)Beam(g.transform,end,end+new Vector3(side*.55f,(finger-1)*.35f,.15f*(finger-1)),.055f,wood,"Branch twig finger");}m.decorations[f].variants[v]=g;g.SetActive(false);}
            templates.gameObject.SetActive(false);
        }
        static Animator[] Crowd(Transform root){string path="Assets/"+Folder+"/Materials/Winter villagers.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(controller==null)controller=AnimatorController.CreateAnimatorControllerAtPath(path);foreach(var pair in new[]{("Idle","idle1"),("Cheer","cheer")}){var machine=controller.layers[0].stateMachine;var state=machine.states.FirstOrDefault(s=>s.state.name==pair.Item1).state;if(state==null)state=machine.AddState(pair.Item1);if(state.motion==null)state.motion=AssetDatabase.LoadAllAssetsAtPath(Human+pair.Item2+".FBX").OfType<AnimationClip>().First(c=>c.humanMotion&&!c.name.StartsWith("__"));if(pair.Item1=="Idle")machine.defaultState=state;EditorUtility.SetDirty(state);EditorUtility.SetDirty(machine);}EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();var people=new List<Animator>();for(int i=0;i<16;i++){var model=AssetDatabase.LoadAssetAtPath<GameObject>(Human+(i%2==0?"business01_m":"business01_f")+".FBX");if(model==null)throw new InvalidOperationException("Actual shared humanoid model required.");var g=UnityEngine.Object.Instantiate(model,root);g.transform.localPosition=new Vector3(-30+i*4,0,45);g.transform.localScale=Vector3.one*2;var a=g.GetComponent<Animator>();if(a==null||a.avatar==null||!a.avatar.isHuman)throw new InvalidOperationException("Genuine humanoid avatar required.");a.runtimeAnimatorController=controller;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;people.Add(a);}return people.ToArray();}
        static AudioClip[] Audio(){string[] paths={"Assets/Heat - Complete Modern UI/Audio/Click.wav","Assets/TruckBilliards/Audio/Ball.wav","Assets/NWH/Vehicle Physics 2/Sound/Transmission/Gear1.wav","Assets/TruckBilliards/Audio/Strike.wav","Assets/TruckDockDiving/Audio/Ordinary applause.wav","Assets/TruckHockey/Audio/GoalHorn.wav","Assets/TruckHockey/Audio/FinalWhistle.wav"};return paths.Select(path=>{var c=AssetDatabase.LoadAssetAtPath<AudioClip>(path);if(c==null)throw new InvalidOperationException("Existing audio required: "+path);return c;}).ToArray();}
